referenceSolutions.javascript:
export function maximumProfitInJobScheduling(jobs            )         {
const a=jobs.map(x=>[...x]).sort((x,y)=>x[1]-y[1]);const dp=Array(a.length+1).fill(0);for(let i=0;i<a.length;i++){let l=0,r=i;while(l<r){const m=(l+r)>>1;if(a[m][1]<=a[i][0])l=m+1;else r=m;}dp[i+1]=Math.max(dp[i],a[i][2]+dp[l]);}return dp[a.length];
}

